{
  "name": "opencode-dock-badge",
  "version": "1.0.0",
  "description": "macOS Dock badge for OpenCode Desktop — shows how many sessions need your attention or have unread replies. Count clears only when you actually open each session.",
  "license": "MIT",
  "author": "wuwu",
  "homepage": "https://github.com/changjianghome/opencode-dock-badge#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/changjianghome/opencode-dock-badge.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-desktop",
    "dock-badge",
    "notification",
    "macos"
  ],
  "type": "module",
  "exports": {
    ".": "./src/index.js",
    "./gui-experimental": "./dist/gui-experimental.cjs"
  },
  "files": [
    "src",
    "dist",
    "README.md"
  ],
  "scripts": {
    "build": "vite build"
  },
  "dependencies": {
    "@opencode/plugin": "2.2.5"
  },
  "devDependencies": {
    "vite": "^7.0.0",
    "vite-plugin-solid": "^2.11.0",
    "solid-js": "^1.9.0"
  }
}
